const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
function icons(root=document){$$('[data-icon]',root).forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('kasai-kogo:'+key))??fallback;}catch{return fallback;}};
let saveWarning=false;function save(key,value){try{localStorage.setItem('kasai-kogo:'+key,JSON.stringify(value));return true;}catch{if(!saveWarning){toast('端末に保存できません。バックアップ保存をご利用ください。');saveWarning=true;}return false;}}
let entries=[],sources=[],board=null,modalBoard=null,toastTimer,drawTool='pen',drawColor='#f0efdf',drawWidth=3;
const state={page:'home',query:'',filter:'すべて',selected:'',entryTab:'meaning',favorites:read('favorites',[]),recent:read('recent',[]),favoritesOnly:false,resultLimit:70,settings:read('settings',{voice:'',rate:1,large:false,contrast:false,texture:true,readings:''}),direction:'modern-classical',translationText:read('translationText','春の雨が静かに降っています。'),translation:null,poemType:read('poemType','haiku'),poemText:read('poemText','春の雨\n窓に小さな\n川をひく'),poemReading:read('poemReading','はるのあめ\nまどにちいさな\nかわをひく'),poemAnalysis:null,poems:read('poems',[]),notes:read('notes',[{id:'first',title:'はじめの黒板',strokes:[],text:'',grid:false}]),noteId:read('noteId','first'),annotation:false};
if(!state.notes.length)state.notes=[{id:'first',title:'はじめの黒板',strokes:[],text:'',grid:false}];
const reader=new Reader({onState:s=>{const play=$('#audio-play');play.innerHTML=icon(s.playing&&!s.paused?'pause':'play');play.setAttribute('aria-label',s.playing&&!s.paused?'読み上げを一時停止':'読み上げを開始');$('#audio-title').textContent=s.label||'ことばを、耳から。';$('#audio-status').textContent=s.message||(s.paused?'一時停止中':s.playing?`読み上げ中 ${s.item+1} / ${s.total}`:'読んでいるページを読み上げます');},onItem:item=>{if(item?.entryId&&state.page==='dictionary'&&state.selected!==item.entryId){state.selected=item.entryId;renderDictionary();}}});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function settingsApply(){document.body.classList.toggle('large-text',state.settings.large);document.body.classList.toggle('high-contrast',state.settings.contrast);document.body.classList.toggle('reduce-texture',!state.settings.texture);reader.voiceName=state.settings.voice;reader.rate=Number(state.settings.rate)||1;$('#audio-speed').value=String(reader.rate);}
function normalize(s){return String(s||'').normalize('NFKC').toLowerCase().replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96)).replace(/[\s・]/g,'');}
function entryByWord(word){return entries.find(e=>[e.headword,e.reading,e.pronunciation].some(v=>normalize(v)===normalize(word)));}
function bookmarkLabel(id){return state.favorites.includes(id)?'しおりを外す':'しおりを挟む';}
function entrySpeech(e){
  let parts=[`${e.pronunciation||e.reading||e.headword}。${e.partOfSpeech}。ひとことでいうと、${e.summary}`];
  for(const [i,m] of (e.meanings||[]).entries())parts.push(`意味、${i+1}。${m.definition}。${m.detail||''}`);
  for(const ex of e.examples||[])parts.push(`用例。${ex.reading||speechText(ex.classical,entries)}。現代語では、${ex.modern}`);
  if(e.usage)parts.push(`使い方。${e.usage}`);if(e.caution)parts.push(`注意。${e.caution}`);
  const forms=conjugate(e);if(forms.length)parts.push(`活用。${forms.map(f=>`${f.form}、${speechText(f.value,entries)}、${f.connection||''}`).join('。')}`);
  return customReading(parts.join('。'));
}
function customReading(text){let out=String(text||'');for(const line of state.settings.readings.split('\n')){const p=line.indexOf('=');if(p>0){const word=line.slice(0,p).trim(),reading=line.slice(p+1).trim();if(word&&reading)out=out.split(word).join(reading);}}return out;}
function currentQueue(){
  if(state.page==='dictionary'){let list=filtered();if(!list.length&&state.selected)list=entries.filter(e=>e.id===state.selected);return list.map(e=>({label:e.headword,text:()=>entrySpeech(e),entryId:e.id}));}
  if(state.page==='translate')return [{label:'ことばの翻訳・解説',text:customReading([state.translationText,state.translation?.output,state.translation?.summary,...(state.translation?.tokens||[]).filter(t=>t.known).map(t=>[t.surface,t.pos,t.form,t.meaning,t.note].filter(Boolean).join('、')),...(state.translation?.notes||[])].filter(Boolean).join('。'))}];
  if(state.page==='poetry')return [{label:poemTypeName(state.poemType)+'の読み上げ',text:customReading((state.poemReading||speechText(state.poemText,entries)).replace(/\n/g,'。')+'。'+(state.poemAnalysis?.summary||'')+'。'+(state.poemAnalysis?.suggestions||[]).join('。'))}];
  if(state.page==='notebook'){const note=currentNote();return [{label:note.title,text:customReading(note.text)}];}
  const e=entryByWord('あはれ')||entries[0];return e?[{label:'今日の一語：'+e.headword,text:entrySpeech(e),entryId:e.id}]:[];
}
function playCurrent(){if(reader.playing){reader.toggle();return;}const queue=currentQueue();reader.setQueue(queue,state.page==='dictionary'?Math.max(0,queue.findIndex(e=>e.entryId===state.selected)):0);reader.start();}
function speak(text,label){reader.setQueue([{text:customReading(text),label}]);reader.start();}
function updateSidebar(){const badge=$('#bookmark-count');badge.textContent=state.favorites.length;badge.hidden=!state.favorites.length;$('#entry-count').textContent=entries.length.toLocaleString();$('#recent-words').innerHTML=state.recent.slice(0,5).map(id=>{const e=entries.find(x=>x.id===id);return e?`<button data-entry="${h(id)}">${h(e.headword)}</button>`:'';}).join('')||'<span class="small muted">ひいたことばがここに並びます</span>';}
function navigate(page,{query,word,entry,favorites=false}={}){
  if(board){board.destroy();board=null;}reader.stop();state.annotation=false;state.page=['home','dictionary','translate','poetry','notebook'].includes(page)?page:'home';state.favoritesOnly=favorites;if(query!==undefined){state.query=query;state.selected='';state.resultLimit=70;state.filter='すべて';}if(entry)state.selected=entry;if(word){const e=entryByWord(word);state.query=word;state.selected=e?.id||'';state.filter='すべて';}history.replaceState(null,'','#'+state.page);document.body.dataset.page=state.page;$$('.main-nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));render();window.scrollTo({top:0,behavior:'instant'});
}
function render(){const fn={home:renderHome,dictionary:renderDictionary,translate:renderTranslate,poetry:renderPoetry,notebook:renderNotebook};fn[state.page]();updateSidebar();}
const searchForm=(value='',placeholder='古語・現代語・読み方から探す')=>`<div class="search-wrap"><form class="search-form" id="search-form">${icon('search')}<input id="search-input" name="q" autocomplete="off" aria-label="古語を検索" placeholder="${h(placeholder)}" value="${h(value)}"><button type="button" class="handwrite-button" data-action="handwriting" data-target="search-input" aria-label="手書きで検索">${icon('pen')}<span>手書き</span></button><button class="primary-button" type="submit">検索</button></form></div>`;
function searchBind(){const form=$('#search-form');if(form)form.onsubmit=e=>{e.preventDefault();navigate('dictionary',{query:$('#search-input').value.trim()});};}
function renderHome(){
  const e=entryByWord('あはれ')||entries[0];$('#main').innerHTML=`<section class="home-hero"><p class="hero-kicker">古典のことばを、もっと身近に。</p><h1 class="chalk">ことばをひらく。<br><span>千年の心にふれる。</span></h1><p class="hero-subtitle">調べる、聴く、書いてみる。<br>あなたのペースで、古語と親しむ黒板辞典。</p><img class="hero-art" src="./assets/plum-chalk.svg" alt="チョークで描いた月と梅の枝" width="430" height="290"></section>${searchForm()}<div class="search-suggestions"><span>こんなことばから</span>${['あはれ','をかし','いみじ','いと','つれづれ'].map(w=>`<button data-word="${w}">${w}</button>`).join('')}</div><div class="home-grid"><section class="chalk-card"><div class="card-top"><span>${icon('book')}今日の一語</span><button class="icon-button" data-action="featured-audio" aria-label="今日の一語を読み上げる">${icon('volume')}</button></div><div class="featured-head"><h2>${h(e?.headword||'あはれ')}</h2><span class="tag">${h(e?.partOfSpeech||'感動詞')}</span></div><p class="featured-meaning">${h(e?.meanings?.[0]?.definition||'しみじみと心を動かされること。')}</p><p class="small muted">${h(e?.summary||'景色にも、人にも。心に触れた感動を表すことば。')}</p><div class="featured-foot"><span>ことばの奥にある、心を知る。</span><button class="text-button" data-entry="${h(e?.id)}">詳しくひく ${icon('book')}</button></div></section><section class="chalk-card poem-card"><div class="card-top"><span>${icon('leaf')}あなたの、十七音。</span><span class="tag">俳句・川柳・短歌</span></div><div class="poem-lines"><span>春の雨</span><span>窓に小さな</span><span>川をひく</span></div><p>音を数えて、ことばを選ぶ。創作例から始めよう。</p><div class="featured-foot"><span>五・七・五、その先へ。</span><button class="text-button" data-page="poetry">句を詠む ${icon('pen')}</button></div></section></div><div class="section-header"><h2>今日は、どんなふうに学ぶ？</h2><span class="muted">書くことから、わかることへ。</span></div><div class="path-grid"><button class="path-card" data-page="dictionary">${icon('book')}<h3>ことばを深く知る</h3><p>意味・用例・活用を、やさしく。<br>ひとことの要約も添えて。</p></button><button class="path-card" data-page="translate">${icon('translate')}<h3>いまの言葉、昔の言葉</h3><p>現代語と古語を行き来して、<br>表現と文法を見比べる。</p></button><button class="path-card" data-page="notebook">${icon('pen')}<h3>まっさらな黒板に</h3><p>線を引く、自由に書き込む。<br>気づきを、あなたの筆跡で。</p></button></div><p class="home-foot">ひとつのことばが、いつか一首になる。</p><div class="home-corpus"><button class="text-button" data-action="about">収録内容・出典</button><span>独自学習語釈 ${entries.length.toLocaleString()} 項目</span></div>`;searchBind();}
function filtered(){const q=normalize(state.query);let list=entries.filter(e=>(!state.favoritesOnly||state.favorites.includes(e.id))&&(state.filter==='すべて'||(state.filter==='動詞'?/^動詞/.test(e.partOfSpeech):e.partOfSpeech.includes(state.filter))));if(q){list=list.map(e=>{const w=[e.headword,e.reading,e.pronunciation,...(Array.isArray(e.modern)?e.modern:[e.modern||''])].map(normalize);const exact=w.includes(q),prefix=w.some(v=>v.startsWith(q)),word=w.some(v=>v.includes(q));const all=normalize([e.summary,e.usage,...e.meanings.map(m=>m.definition+' '+m.detail),...(e.tags||[])].join(' '));return {e,score:exact?0:prefix?1:word?2:all.includes(q)?3:9};}).filter(x=>x.score<9).sort((a,b)=>a.score-b.score||a.e.reading.localeCompare(b.e.reading,'ja')).map(x=>x.e);}else list.sort((a,b)=>a.reading.localeCompare(b.reading,'ja'));return list;}
function renderDictionary(){
  if(board){board.destroy();board=null;}const list=filtered();let entry=entries.find(e=>e.id===state.selected);if(!entry||!list.some(e=>e.id===entry.id)){entry=list[0];state.selected=entry?.id||'';}if(entry){state.recent=[entry.id,...state.recent.filter(id=>id!==entry.id)].slice(0,12);save('recent',state.recent);updateSidebar();}
  $('#main').innerHTML=`<div class="page-heading page-heading-row"><div><h1>${state.favoritesOnly?'しおりのことば':'辞典をひく'}</h1><p>${state.favoritesOnly?'また会いたいことばを、あなたの一冊に。':'語釈、用例、活用。ことばの意味を、ひとつずつ。'}</p></div><button class="outline-button" data-action="dictionary-queue">${icon('headphones')}連続で聴く</button></div>${searchForm(state.query)}<div class="filters">${['すべて','動詞','形容詞','形容動詞','名詞','副詞','助動詞','助詞'].map(p=>`<button class="filter-chip ${state.filter===p?'active':''}" data-filter="${p}">${p}</button>`).join('')}${state.favoritesOnly?'<button class="filter-chip" data-action="all-entries">全語に戻る</button>':''}</div><div class="dictionary-layout ${entry?'show-detail':''}" id="dictionary-layout"><aside class="result-list"><div class="result-list-head">${list.length.toLocaleString()} 項目 ${state.query?'・「'+h(state.query)+'」':''}</div>${list.slice(0,state.resultLimit).map(e=>`<button class="result-item ${e.id===state.selected?'selected':''}" data-select="${h(e.id)}"><strong>${h(e.headword)}</strong><small>${h(e.partOfSpeech)}</small><span>${h(e.summary.slice(0,55))}${e.summary.length>55?'…':''}</span></button>`).join('')}${list.length>state.resultLimit?'<button class="outline-button section-gap" data-action="more-results">続きを表示</button>':''}${!list.length?'<p class="small muted">該当する見出しがありません。</p>':''}</aside><article class="entry-paper" id="entry-paper">${entry?entryHTML(entry):emptyDictionary()}</article></div>${!entry?'<div class="empty-state">'+emptyDictionary()+'</div>':''}`;searchBind();loadEntryInk();
}
function emptyDictionary(){return `${icon('search')}<h2>このことばは、まだ未収録です。</h2><p>読み仮名や別の表記でも検索できます。現在の独自解説は ${entries.length.toLocaleString()} 項目です。</p><a class="outline-button" href="https://ja.wiktionary.org/w/index.php?search=${encodeURIComponent(state.query)}" target="_blank" rel="noopener noreferrer">公開辞典で調べる</a><p class="small muted">別サイトが開きます。古語以外の項目も含みます。</p>`;}
function entryHTML(e){const forms=conjugate(e);let content='';
  if(state.entryTab==='meaning')content=`<div class="summary-box"><span class="label">ひとことでいうと</span><p>${h(e.summary)}</p></div>${e.meanings.map((m,i)=>`<section class="definition"><h3><span class="definition-index">${i+1}.</span>${h(m.definition)}</h3><p>${h(m.detail)}</p></section>`).join('')}${e.examples?.[0]?exampleHTML(e.examples[0]):''}<h3 class="content-subhead">使うときの手がかり</h3><p class="small">${h(e.usage)}</p>${e.caution?`<div class="info-note">${icon('info')}${h(e.caution)}</div>`:''}`;
  else if(state.entryTab==='examples')content=`<h3 class="content-subhead">文の中で、意味をつかむ</h3>${e.examples.map(exampleHTML).join('')}<h3 class="content-subhead">使い方・ニュアンス</h3><p class="small">${h(e.usage)}</p>${e.caution?`<div class="summary-box"><span class="label">間違えやすいところ</span><p>${h(e.caution)}</p></div>`:''}<p class="short-notice">用例は学習用の創作文です。古典作品からの引用ではありません。</p>`;
  else content=forms.length?`<p class="small muted">${h(e.conjugation)}。形と接続を見比べましょう。</p><div class="table-scroll"><table class="conjugation-table"><thead><tr><th>活用形</th><th>かたち</th><th>接続・目印</th></tr></thead><tbody>${forms.map(f=>`<tr><td>${h(f.form)}</td><td>${h(f.value)}</td><td>${h((f.connection||'').replace('本活用とカリ活用を併記しています。助動詞を続けるときなどにカリ活用を用います。 ',''))}</td></tr>`).join('')}</tbody></table></div><div class="info-note">${icon('info')}活用は代表的な学校文法に基づく学習用表示です。異形や時代による用法は語釈・注意も併せて確認してください。</div>`:`<div class="summary-box"><span class="label">活用について</span><p>この見出しには活用表を持たせていません。</p></div><p class="small">${h(e.partOfSpeech)}。${h(e.usage)}</p>`;
  return `<button class="mobile-results-toggle" data-action="show-results">${icon('back')}検索結果 ${filtered().length} 項目を見る</button><div class="entry-topline"><span class="tag">${h(e.partOfSpeech)}${e.conjugation?' ・ '+h(e.conjugation):''}</span><div class="entry-actions"><button class="icon-button ${state.favorites.includes(e.id)?'yellow':''}" data-action="bookmark" aria-label="${bookmarkLabel(e.id)}" title="${bookmarkLabel(e.id)}">${icon('bookmark')}</button><button class="icon-button" data-action="entry-audio" aria-label="この項目をすべて読み上げる" title="この項目をすべて読む">${icon('volume')}</button><button class="icon-button" data-action="annotate" aria-label="このページに手書きする" title="書き込む">${icon('pen')}</button></div></div><h2 class="entry-title">${h(e.headword)}</h2><p class="entry-reading">読み：${h(e.reading)}${e.pronunciation&&e.pronunciation!==e.reading?'　／　音読：'+h(e.pronunciation):''}</p><div class="entry-tabs" role="tablist"><button role="tab" aria-selected="${state.entryTab==='meaning'}" class="${state.entryTab==='meaning'?'active':''}" data-tab="meaning">意味・要約</button><button role="tab" aria-selected="${state.entryTab==='examples'}" class="${state.entryTab==='examples'?'active':''}" data-tab="examples">用例・使い方</button><button role="tab" aria-selected="${state.entryTab==='conjugation'}" class="${state.entryTab==='conjugation'?'active':''}" data-tab="conjugation">活用</button></div><div id="annotation-tools"></div><div id="entry-content" style="position:relative">${content}${e.related?.length?`<h3 class="content-subhead">あわせてひく</h3><div class="related-words">${e.related.map(w=>`<button data-word="${h(w)}">${h(w)}</button>`).join('')}</div>`:''}<p class="reading-notice">葛西書店・独自学習語釈　／　<a href="https://ja.wiktionary.org/w/index.php?search=${encodeURIComponent(e.reading)}" target="_blank" rel="noopener noreferrer">公開辞典で照合</a></p><canvas class="entry-note-overlay" id="entry-ink" aria-label="辞典への手書きメモ"></canvas></div>`;
}
function exampleHTML(ex){return `<div class="example-box"><div class="example-label">学習用例</div><p class="classical">${h(ex.classical)}</p><p class="modern">${h(ex.modern)}</p><button class="text-button small" data-speak="${h(ex.reading||speechText(ex.classical,entries))}" data-label="用例の読み上げ" aria-label="用例を読み上げる">${icon('volume')}用例を聴く</button></div>`;}
function renderTranslate(){
 const t=state.translation;$('#main').innerHTML=`<div class="page-heading"><h1>いまの言葉、昔の言葉。</h1><p>意味をたどりながら、自分のことばで古語に親しむ。</p></div><div class="segmented-control"><button data-direction="modern-classical" class="${state.direction==='modern-classical'?'active':''}">現代語から古語</button><button data-direction="classical-modern" class="${state.direction==='classical-modern'?'active':''}">古語から現代語</button></div><div class="editor-grid"><section class="editor-card"><h2>${icon('pen')}${state.direction==='modern-classical'?'いまの言葉で書く':'古語を書いてみる'}</h2><label class="sr-only" for="translation-input">翻訳する文章</label><textarea id="translation-input" rows="6" maxlength="3000" placeholder="単語や短い文章を入力してください">${h(state.translationText)}</textarea><div class="field-row"><span id="translation-count" class="short-notice">${state.translationText.length} / 3,000 字</span><button class="text-button small" data-action="handwriting" data-target="translation-input">${icon('pen')}手書きで入力</button></div><div class="field-row"><button class="primary-button" data-action="translate">${icon('translate')}訳して解説する</button><button class="icon-button" data-action="clear-translation" aria-label="文章を消す">${icon('trash')}</button></div><div class="example-picks"><span class="small muted">例：</span><button data-translation-example="春の雨が静かに降っています。">春の雨</button><button data-translation-example="月がとても美しい。">美しい月</button><button data-translation-example="花はいとをかし。" data-example-direction="classical-modern">花はいとをかし</button></div></section><section class="editor-card"><h2>${icon('book')}ことばの変換候補</h2><div class="translation-output ${!t?'muted':''}" id="translation-output">${h(t?.output||'ここに表現の候補が表示されます。\n意味や活用の解説と、一緒に読み比べましょう。')}</div><div class="field-row"><span class="tag">辞典・文法に基づく参考変換</span><div class="field-actions"><button class="icon-button" data-action="translation-audio" aria-label="変換結果を読み上げる" ${!t?'disabled':''}>${icon('volume')}</button><button class="icon-button" data-action="copy-translation" aria-label="変換結果をコピー" ${!t?'disabled':''}>${icon('copy')}</button></div></div></section></div>${t?`<section class="explanation-panel"><h2 class="content-subhead">ことばをほどく</h2><div class="summary-box"><span class="label">解説の要約</span><p>${h(t.summary)}</p></div><div class="token-list">${(t.tokens||[]).map(token=>`<button class="token" ${token.entryId?'data-entry="'+h(token.entryId)+'"':''} title="${h(token.note||token.meaning||'')}"><strong>${h(token.surface)}</strong><small>${h(token.pos||'未解析')} ${h(token.form||'')}</small><small>${h(token.meaning||'文脈・読みを確認')}</small></button>`).join('')}</div><div class="token-details">${(t.tokens||[]).filter(x=>x.note).slice(0,80).map(token=>`<details><summary>${h(token.surface)} の文法・使い方</summary><p>${h(token.meaning)}。${h(token.note)}</p></details>`).join('')}</div><ul class="advice-list">${(t.notes||[]).map(n=>`<li>${h(n)}</li>`).join('')}</ul></section>`:''}<div class="info-note">${icon('info')}内蔵語彙・文型による学習用の変換です。長文の文脈、敬意の向き、主語の省略などは自動で確定できません。未対応の箇所は元の文章を残します。解釈の候補としてご利用ください。</div>`;
 $('#translation-input').oninput=e=>{state.translationText=e.target.value;state.translation=null;$('#translation-output').textContent='入力が変わりました。「訳して解説する」で確認してください。';$('.explanation-panel')?.remove();$$('[data-action=translation-audio],[data-action=copy-translation]').forEach(b=>b.disabled=true);save('translationText',state.translationText);$('#translation-count').textContent=state.translationText.length+' / 3,000 字';};
}
const poemTypeName=t=>({haiku:'俳句',senryu:'川柳',tanka:'短歌'}[t]||'俳句');
function renderPoetry(){
 const a=state.poemAnalysis;$('#main').innerHTML=`<div class="page-heading"><h1>ことばを選んで、句を詠む。</h1><p>俳句、川柳、短歌。あなたの気づきに、リズムを添えて。</p></div><div class="segmented-control">${[['haiku','俳句','五・七・五'],['senryu','川柳','五・七・五'],['tanka','短歌','五・七・五・七・七']].map(([t,n])=>`<button data-poem-type="${t}" class="${state.poemType===t?'active':''}">${n}</button>`).join('')}</div><div class="poetry-workspace"><section class="editor-card"><h2>${icon('pen')}${poemTypeName(state.poemType)}を書く</h2><label class="field-label" for="poem-input">ひと区切りずつ改行して書いてください</label><textarea class="poem-input" id="poem-input" maxlength="600" rows="${state.poemType==='tanka'?5:3}" placeholder="ここに作品を書く">${h(state.poemText)}</textarea><div class="field-row"><span class="tag">${state.poemType==='tanka'?'五・七・五・七・七':'五・七・五'}</span><button class="text-button small" data-action="handwriting" data-target="poem-input">${icon('pen')}手書きで入力</button></div><label class="field-label" for="poem-reading">音数・読み上げのための読み仮名</label><textarea id="poem-reading" rows="${state.poemType==='tanka'?5:3}" maxlength="1000" placeholder="ひらがなで、本文と同じ位置で改行">${h(state.poemReading)}</textarea><p class="short-notice">拗音「きゃ」は1音。「ん」「っ」「ー」は各1音。漢字の読みを確認すると正しく数えられます。</p><div class="field-row"><button class="primary-button" data-action="analyze-poem">${icon('leaf')}音数・ことばを確認</button><div class="field-actions"><button class="icon-button" data-action="poem-audio" aria-label="作品を読み上げる">${icon('volume')}</button><button class="icon-button" data-action="save-poem" aria-label="作品を保存する" title="作品を保存">${icon('save')}</button></div></div><div class="example-picks"><span class="small muted">創作例：</span><button data-action="poem-example">例文を入れる</button><button data-action="poem-to-classical">古語表現を調べる</button></div></section><section class="editor-card" id="poem-result"><h2>${icon('leaf')}あなたの一篇</h2><div class="poem-preview" id="poem-preview">${poemPreviewHTML()}</div>${a?`<div class="mora-row">${a.lines.map(l=>`<div class="mora-cell ${l.exact?'match':'mismatch'}"><strong>${l.mora===null?'?':l.mora}</strong><small>目安 ${l.target??'—'} 音</small></div>`).join('')}</div><p class="poem-status">${a.needsReading?'読み仮名を確認してください':a.isRegular?'基本の音数がそろっています':'字余り・字足らずも表現のひとつです'}</p><h3 class="content-subhead">${state.poemType==='haiku'?'季語・切れ字の手がかり':'表現の手がかり'}</h3><div class="related-words">${a.seasonWords.map(k=>`<span class="tag">${h(k.word)} ・ ${h(k.season)}</span>`).join('')||'<span class="small muted">内蔵の季語候補には一致しませんでした</span>'}</div>${a.kireji?.length?'<p class="small muted section-gap">切れ字の候補：'+a.kireji.map(k=>h(k.word)+'（'+h(k.line)+'句目）').join('、')+'</p>':''}<p class="small muted section-gap">${h(a.summary)}</p>`:'<div class="empty-state"><p>読み仮名を添えて確認すると、<br>音の数と表現のヒントが並びます。</p></div>'}</section></div>${a?`<section class="explanation-panel"><h2 class="content-subhead">推敲の手がかり</h2><ul class="advice-list">${[...(a.suggestions||[]),...(a.notes||[])].map(n=>`<li>${h(n)}</li>`).join('')}</ul></section>`:''}<div class="info-note">${icon('info')}${state.poemType==='haiku'?'五・七・五と季語を基本の目安にしています。無季や自由律の俳句もあり、型から外れることを誤りとは判定しません。':state.poemType==='senryu'?'川柳は人の営みや心の動きを詠む表現です。季語は必須ではありません。':'短歌は五・七・五・七・七を基本にします。季語は必須ではありません。'} 季語と切れ字は登録語との一致候補で、文脈を含めた断定ではありません。</div><section class="section-gap"><div class="section-header"><h2>あなたの作品帖</h2><span class="muted">この端末に保存</span></div><div class="saved-poems">${state.poems.length?state.poems.map(p=>`<article class="saved-poem"><p>${h(p.text)}</p><div class="field-row"><span>${poemTypeName(p.type)}</span><div><button class="icon-button" data-open-poem="${h(p.id)}" aria-label="作品を開く">${icon('pen')}</button><button class="icon-button" data-delete-poem="${h(p.id)}" aria-label="作品を削除">${icon('trash')}</button></div></div></article>`).join(''):'<p class="small muted">保存ボタンで、ここに作品を残せます。</p>'}</div></section>`;
 $('#poem-input').oninput=e=>{state.poemText=e.target.value;invalidatePoem();save('poemText',state.poemText);$('#poem-preview').innerHTML=poemPreviewHTML();};$('#poem-reading').oninput=e=>{state.poemReading=e.target.value;invalidatePoem();save('poemReading',state.poemReading);};
}
function invalidatePoem(){state.poemAnalysis=null;$('.explanation-panel')?.remove();const result=$('#poem-result');if(result){[...result.children].filter(n=>n.tagName!=='H2'&&!n.classList.contains('poem-preview')).forEach(n=>n.remove());result.insertAdjacentHTML('beforeend','<p class="info-note">入力が変わりました。「音数・ことばを確認」で確認してください。</p>');}}
function poemPreviewHTML(){return state.poemText.split(/\n/).filter(Boolean).slice(0,6).reverse().map(l=>`<span>${h(l)}</span>`).join('')||'<span class="muted">あなたのことばを、ここに。</span>';}
function currentNote(){return state.notes.find(n=>n.id===state.noteId)||state.notes[0];}
function inkToolbar(annotate=false){return `<div class="ink-toolbar" role="toolbar" aria-label="チョークの道具"><button class="icon-button ${drawTool==='pen'?'active':''}" data-tool="pen" aria-label="チョーク" title="チョーク">${icon('pen')}</button><button class="icon-button ${drawTool==='highlighter'?'active':''}" data-tool="highlighter" aria-label="マーカー" title="マーカー">${icon('highlighter')}</button><button class="icon-button ${drawTool==='line'?'active':''}" data-tool="line" aria-label="直線" title="直線">${icon('line')}</button><button class="icon-button ${drawTool==='eraser'?'active':''}" data-tool="eraser" aria-label="黒板消し" title="黒板消し">${icon('eraser')}</button><span class="ink-separator"></span>${[['#f0efdf','白'],['#e8ce88','黄'],['#e7aaa4','桃'],['#9bc9d1','青']].map(([c,n])=>`<button class="color-swatch ${drawColor===c?'active':''}" data-color="${c}" style="--swatch:${c}" aria-label="${n}のチョーク" title="${n}"></button>`).join('')}<label class="ink-label" for="ink-width">太さ</label><input id="ink-width" type="range" min="1" max="12" value="${drawWidth}" aria-label="線の太さ"><span class="toolbar-spacer"></span><button class="icon-button" data-action="ink-undo" aria-label="元に戻す">${icon('undo')}</button><button class="icon-button" data-action="ink-redo" aria-label="やり直す">${icon('redo')}</button><button class="icon-button" data-action="ink-clear" aria-label="筆跡をすべて消す">${icon('trash')}</button>${annotate?'<button class="outline-button" data-action="finish-annotation">書き込み完了</button>':''}</div>`;}
function renderNotebook(){if(board){board.destroy();board=null;}const note=currentNote();state.noteId=note.id;$('#main').innerHTML=`<div class="page-heading page-heading-row"><div><h1>自由に書く、黒板ノート。</h1><p>線を引く、考えをつなぐ。ことばの気づきを自由な筆跡で。</p></div><button class="outline-button" data-action="new-note">${icon('plus')}新しい黒板</button></div><div class="notebook-tabs">${state.notes.map(n=>`<button class="${note.id===n.id?'active':''}" data-note="${h(n.id)}">${h(n.title)}</button>`).join('')}</div><div class="notebook-header"><label class="sr-only" for="note-title">黒板の名前</label><input id="note-title" value="${h(note.title)}" maxlength="40"><button class="icon-button" data-action="note-grid" aria-label="方眼の表示切り替え" title="方眼">${icon('grid')}</button><button class="icon-button" data-action="note-download" aria-label="黒板を画像として保存" title="画像で保存">${icon('download')}</button><button class="icon-button" data-action="delete-note" aria-label="この黒板を削除" title="黒板を削除">${icon('trash')}</button></div>${inkToolbar()}<div class="notebook-canvas-wrap ${note.grid?'grid':''}" id="note-canvas-wrap"><canvas id="note-canvas" aria-label="自由に書き込める黒板"></canvas><span class="notebook-placeholder ${note.strokes?.length?'hidden':''}" id="notebook-placeholder">チョークを持って、自由に書いてみよう。</span></div><div class="notebook-footer"><span>ペン・指・マウス対応 ／ 筆圧対応端末では強弱を反映</span><span>この端末に保存</span></div><div class="note-text"><label class="field-label" for="note-text">文字のメモ・読み上げ用テキスト</label><textarea id="note-text" rows="3" placeholder="自由な筆跡は画像として保存されます。読み上げたい内容はここに入力してください。">${h(note.text)}</textarea><div class="field-row"><button class="text-button" data-action="handwriting" data-target="note-text">${icon('pen')}手書き文字を入力</button><button class="outline-button" data-action="note-audio">${icon('volume')}メモを聴く</button></div></div>`;
 board=new InkBoard($('#note-canvas'),{color:drawColor,width:drawWidth,tool:drawTool,onChange:strokes=>{note.strokes=strokes;save('notes',state.notes);$('#notebook-placeholder')?.classList.toggle('hidden',strokes.length>0);}});board.setStrokes(note.strokes||[]);bindInk();$('#note-title').onchange=e=>{note.title=e.target.value.trim()||'名もない黒板';save('notes',state.notes);renderNotebook();};$('#note-text').oninput=e=>{note.text=e.target.value;save('notes',state.notes);};
}
function bindInk(){const range=$('#ink-width');if(range)range.oninput=e=>{drawWidth=+e.target.value;board?.setWidth(drawWidth);};}
function loadEntryInk(){const canvas=$('#entry-ink');if(!canvas)return;const key=state.selected+':'+state.entryTab;const all=read('annotations',{});board=new InkBoard(canvas,{color:drawColor,width:drawWidth,tool:drawTool,onChange:strokes=>{const data=read('annotations',{});data[key]=strokes;save('annotations',data);}});board.setStrokes(all[key]||[]);board.setEnabled(false);}
function annotate(){if(!$('#entry-ink'))return;if(board){board.destroy();board=null;}state.annotation=true;$('#annotation-tools').innerHTML=inkToolbar(true);const key=state.selected+':'+state.entryTab;const saved=read('annotations',{});const canvas=$('#entry-ink');canvas.classList.add('drawing');board=new InkBoard(canvas,{color:drawColor,width:drawWidth,tool:drawTool,onChange:strokes=>{saved[key]=strokes;save('annotations',saved);}});board.setStrokes(saved[key]||[]);bindInk();}
function showModal(title,html){if(modalBoard){modalBoard.destroy();modalBoard=null;}$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(modalBoard){modalBoard.destroy();modalBoard=null;}$('#modal').close();}
function confirmAction(title,text,callback){showModal(title,`<p class="settings-paragraph">${h(text)}</p><div class="field-actions"><button class="primary-button" id="confirm-yes">削除する</button><button class="outline-button" id="confirm-no">残しておく</button></div>`);$('#confirm-yes').onclick=()=>{closeModal();callback();};$('#confirm-no').onclick=closeModal;}
function showSettings(){showModal('あなたに合う読み方に',`<div class="setting-row"><label for="voice-choice">日本語の音声<small>端末で使える日本語音声から選びます</small></label><select id="voice-choice"><option value="">端末の標準音声</option>${reader.voices.map(v=>`<option value="${h(v.name)}" ${v.name===state.settings.voice?'selected':''}>${h(v.name)}</option>`).join('')}</select></div><div class="setting-row"><label for="large-text">文字を大きくする</label><input id="large-text" type="checkbox" ${state.settings.large?'checked':''}></div><div class="setting-row"><label for="high-contrast">文字をよりくっきり</label><input id="high-contrast" type="checkbox" ${state.settings.contrast?'checked':''}></div><div class="setting-row"><label for="board-texture">黒板の質感</label><input id="board-texture" type="checkbox" ${state.settings.texture?'checked':''}></div><label class="field-label" for="custom-readings">読み方の登録</label><textarea id="custom-readings" rows="4" placeholder="葛西=かさい\n古語=こご">${h(state.settings.readings)}</textarea><p class="short-notice">「語句=よみ」を1行ずつ。登録した読み方を優先します。</p><p class="settings-paragraph">古語の読みは見出し・用例の読み仮名を優先します。合成音声の発音やイントネーションは端末により異なります。画面ロック中や別アプリ使用中の連続再生は、端末によって停止することがあります。</p><div class="field-actions"><button class="primary-button" id="save-settings">設定を保存</button><button class="outline-button" id="test-voice">音声を試す</button></div><h3 class="content-subhead">学びのバックアップ</h3><p class="short-notice">しおり・黒板・作品はこの端末のブラウザに保存します。他端末へはバックアップを移して読み込めます。</p><div class="field-actions section-gap"><button class="outline-button" id="export-data">${icon('download')}保存データを書き出す</button><label class="outline-button" for="import-data">読み込む<input class="sr-only" id="import-data" type="file" accept="application/json,.json"></label></div>`);
 $('#save-settings').onclick=()=>{state.settings={...state.settings,voice:$('#voice-choice').value,large:$('#large-text').checked,contrast:$('#high-contrast').checked,texture:$('#board-texture').checked,readings:$('#custom-readings').value};save('settings',state.settings);settingsApply();closeModal();toast('読み方と表示を保存しました');};$('#test-voice').onclick=()=>{reader.voiceName=$('#voice-choice').value;speak('ことばをひらく。千年の心にふれる。かさいしょてん、こごじてん。','日本語音声の確認');};$('#export-data').onclick=exportData;$('#import-data').onchange=importData;
}
function showAbout(){showModal('この辞典について',`<p class="settings-paragraph"><strong>古語辞典｜葛西書店</strong><br>2026年11月25日制作・オリジナル学習版</p><div class="summary-box"><span class="label">現在の収録範囲</span><p>独自の学習語釈 ${entries.length.toLocaleString()} 項目。語義・要約・用例・用法と、対応語の活用表を収録しています。</p></div><p class="settings-paragraph">全時代・全用法・全古語を網羅した辞典ではありません。市販の最新版古語辞典の全文を転載したものではなく、未収録語は検索画面から公開辞典で確認できます。内容には校訂の余地があります。専門的な研究や出典の確定には原典・専門辞典も参照してください。</p><h3 class="content-subhead">機能と読み方</h3><ul class="advice-list"><li>見出しは歴史的仮名遣い、音読は現代の学校教育で一般的な読み方を基本にします。</li><li>文章変換は内蔵語彙・活用・文型を使った参考候補です。任意の長文を理解する生成AI翻訳ではありません。</li><li>手書きは一文字ずつ候補を選びます。筆順やくずし字によって認識結果は変わります。</li><li>創作支援では読み仮名から音数を数え、登録した季語・切れ字との一致を示します。</li></ul><h3 class="content-subhead">参考資料・素材</h3><div class="small">${sources.map(s=>`<p><a class="external-link" href="${h(s.url||s.href||'#')}" target="_blank" rel="noopener noreferrer">${h(s.title||s.name||s.url)}</a></p>`).join('')}<p><a class="external-link" href="https://www.lib.pref.yamanashi.jp/reference/ref-haiku.pdf" target="_blank" rel="noopener noreferrer">山梨県立図書館「俳句の調べ方」</a></p><p>手書き字形：KanjiVG © Ulrich Apel and contributors。SVG字形を認識用座標データへ加工。CC BY-SA 3.0。<a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener noreferrer">配布元</a> ／ <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a>。<a class="external-link" href="./kanjivg-license.txt" target="_blank">ライセンス</a></p><p>チョーク書体：Yomogi／SIL Open Font License 1.1。<a class="external-link" href="./assets/Yomogi-OFL.txt" target="_blank">ライセンス</a></p></div><h3 class="content-subhead">プライバシー</h3><p class="settings-paragraph">検索・変換・筆跡候補の照合・作品の確認は端末内で実行します。音声の処理方法は選択した端末音声に依存します。外部辞典リンクを開いた場合はリンク先の方針が適用されます。</p><p class="short-notice">© 2026 葛西書店</p>`);}
async function showHandwriting(target){
 const field=document.getElementById(target),original=field?.value||'';showModal('手書きで、ことばを入力',`<p class="small muted">一文字ずつ、枠に大きく書いてください。候補を選ぶと文字を追加できます。</p><div class="handwriting-result section-gap"><input id="handwritten-text" value="${h(original)}" aria-label="認識した文字"><button class="outline-button" id="handwritten-small" title="最後のかなを大書き・小書きに切り替える">小</button><button class="icon-button" id="handwritten-backspace" aria-label="最後の文字を消す">${icon('back')}</button></div><div class="handwriting-pad"><canvas id="handwriting-canvas" aria-label="一文字を手書きする枠"></canvas></div><div class="handwriting-candidates" id="handwriting-candidates"><span class="small muted">ここに認識候補が並びます</span></div><div class="field-row"><div class="field-actions"><button class="outline-button" id="recognize-handwriting">候補を調べる</button><button class="icon-button" id="handwriting-undo" aria-label="一画戻す">${icon('undo')}</button><button class="icon-button" id="handwriting-clear" aria-label="筆跡を消す">${icon('trash')}</button></div><button class="primary-button" id="use-handwriting">入力する</button></div><p class="info-note">筆順・字形によって候補が変わります。認識結果を確認してから入力してください。自由な筆跡そのものは黒板ノートに残せます。</p>`);
 let timer,request=0;modalBoard=new InkBoard($('#handwriting-canvas'),{color:'#f0efdf',width:3.5,onChange:strokes=>{clearTimeout(timer);request++;if(strokes.length)timer=setTimeout(recognize,430);else if($('#handwriting-candidates'))$('#handwriting-candidates').innerHTML='<span class="small muted">一文字書いてみましょう</span>';}});
 async function recognize(){const current=++request;const ownBoard=modalBoard,container=$('#handwriting-candidates');const strokes=ownBoard?.getStrokes();if(!strokes?.length)return;$('#handwriting-candidates').innerHTML='<span class="small muted">筆跡から候補を調べています…</span>';try{const candidates=await recognizeHandwriting(strokes,{limit:8});if(current!==request||modalBoard!==ownBoard||!container?.isConnected||!$('#modal').open)return;$('#handwriting-candidates').innerHTML=candidates.length?candidates.map(c=>`<button data-candidate="${h(c.text)}">${h(c.text)}</button>`).join(''):'<span class="small muted">候補が見つかりませんでした。大きく書き直してください。</span>';}catch{if($('#handwriting-candidates'))$('#handwriting-candidates').innerHTML='<span class="small muted">認識できませんでした。通信後に再試行してください。</span>';}}
 $('#recognize-handwriting').onclick=recognize;$('#handwriting-clear').onclick=()=>modalBoard?.clear();$('#handwriting-undo').onclick=()=>modalBoard?.undo();$('#handwritten-small').onclick=()=>{const e=$('#handwritten-text'),chars=[...e.value];if(chars.length){chars[chars.length-1]=toggleSmallKana(chars.at(-1));e.value=chars.join('');}};$('#handwritten-backspace').onclick=()=>{const e=$('#handwritten-text');e.value=[...e.value].slice(0,-1).join('');};$('#handwriting-candidates').onclick=e=>{const b=e.target.closest('[data-candidate]');if(!b)return;$('#handwritten-text').value+=b.dataset.candidate;modalBoard?.clear();};$('#use-handwriting').onclick=()=>{const text=$('#handwritten-text').value;const dest=document.getElementById(target);if(dest){dest.value=text;dest.dispatchEvent(new Event('input',{bubbles:true}));}closeModal();if(target==='search-input')navigate('dictionary',{query:text.trim()});};
}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportData(){const data={app:'kasai-kogo',version:1,exported:new Date().toISOString(),favorites:state.favorites,notes:state.notes,poems:state.poems,annotations:read('annotations',{}),settings:state.settings};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'kasai-kogo-backup.json');toast('バックアップを書き出しました');}
async function importData(event){const file=event.target.files?.[0];if(!file)return;if(file.size>15_000_000){toast('15 MB以下のバックアップを選んでください');return;}try{const data=JSON.parse(await file.text());if(data.app!=='kasai-kogo'||data.version!==1||!Array.isArray(data.notes)||!Array.isArray(data.poems)||!Array.isArray(data.favorites))throw Error('invalid');const notes=data.notes.filter(n=>typeof n.title==='string'&&typeof n.id==='string'&&typeof n.text==='string'&&Array.isArray(n.strokes));const poems=data.poems.filter(p=>typeof p.id==='string'&&typeof p.text==='string'&&['haiku','senryu','tanka'].includes(p.type));state.notes=[...new Map([...state.notes,...notes].map(n=>[n.id,n])).values()];state.poems=[...new Map([...state.poems,...poems].map(p=>[p.id,p])).values()];state.favorites=[...new Set([...state.favorites,...data.favorites.filter(x=>typeof x==='string')])];save('notes',state.notes);save('poems',state.poems);save('favorites',state.favorites);if(data.annotations&&typeof data.annotations==='object'&&!Array.isArray(data.annotations))save('annotations',{...read('annotations',{}),...data.annotations});closeModal();render();toast('バックアップを追加・復元しました');}catch{toast('この辞典の有効なバックアップを選んでください');}}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('コピーしました');}catch{showModal('コピーする文章',`<textarea rows="7" readonly>${h(text)}</textarea><p class="short-notice">文章を選択してコピーしてください。</p>`);}}

document.addEventListener('click',async event=>{
 const b=event.target.closest('button,a');if(!b)return;
 if(b.dataset.page){navigate(b.dataset.page);return;}
 if(b.dataset.word){navigate('dictionary',{word:b.dataset.word});return;}
 if(b.dataset.entry){navigate('dictionary',{query:'',entry:b.dataset.entry});return;}
 if(b.dataset.select){state.selected=b.dataset.select;state.annotation=false;renderDictionary();return;}
 if(b.dataset.filter){state.filter=b.dataset.filter;state.selected='';renderDictionary();return;}
 if(b.dataset.tab){state.entryTab=b.dataset.tab;state.annotation=false;renderDictionary();return;}
 if(b.dataset.speak){speak(b.dataset.speak,b.dataset.label||'読み上げ');return;}
 if(b.dataset.direction){state.direction=b.dataset.direction;state.translation=null;renderTranslate();return;}
 if(b.dataset.translationExample){state.translationText=b.dataset.translationExample;state.direction=b.dataset.exampleDirection||'modern-classical';state.translation=null;save('translationText',state.translationText);renderTranslate();return;}
 if(b.dataset.poemType){state.poemType=b.dataset.poemType;state.poemAnalysis=null;save('poemType',state.poemType);renderPoetry();return;}
 if(b.dataset.openPoem){const p=state.poems.find(p=>p.id===b.dataset.openPoem);if(p){state.poemType=p.type;state.poemText=p.text;state.poemReading=p.reading;state.poemAnalysis=null;savePoemDraft();renderPoetry();window.scrollTo({top:0,behavior:'smooth'});}return;}
 if(b.dataset.deletePoem){confirmAction('作品を削除しますか？','この端末の作品帖から削除します。',()=>{state.poems=state.poems.filter(p=>p.id!==b.dataset.deletePoem);save('poems',state.poems);renderPoetry();});return;}
 if(b.dataset.note){state.noteId=b.dataset.note;save('noteId',state.noteId);renderNotebook();return;}
 if(b.dataset.tool){drawTool=b.dataset.tool;board?.setTool(drawTool);$$('[data-tool]').forEach(e=>e.classList.toggle('active',e===b));return;}
 if(b.dataset.color){drawColor=b.dataset.color;board?.setColor(drawColor);$$('[data-color]').forEach(e=>e.classList.toggle('active',e===b));return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='settings')return showSettings();
 if(action==='about')return showAbout();
 if(action==='favorites')return navigate('dictionary',{query:'',favorites:true});
 if(action==='all-entries')return navigate('dictionary',{query:state.query});
 if(action==='handwriting')return showHandwriting(b.dataset.target||'search-input');
 if(action==='featured-audio'){const e=entryByWord('あはれ')||entries[0];return speak(entrySpeech(e),'今日の一語：'+e.headword);}
 if(action==='entry-audio'){const e=entries.find(e=>e.id===state.selected);return speak(entrySpeech(e),e.headword);}
 if(action==='bookmark'){const id=state.selected;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save('favorites',state.favorites);renderDictionary();toast(state.favorites.includes(id)?'しおりを挟みました':'しおりを外しました');return;}
 if(action==='dictionary-queue'){reader.continuous=true;$('#audio-continuous').setAttribute('aria-pressed','true');reader.stop();return playCurrent();}
 if(action==='show-results'){$('#dictionary-layout').classList.remove('show-detail');return;}
 if(action==='more-results'){const scroll=$('.result-list')?.scrollTop||0;state.resultLimit+=70;renderDictionary();$('.result-list').scrollTop=scroll;$('#dictionary-layout').classList.remove('show-detail');return;}
 if(action==='annotate'){if(!state.annotation)annotate();return;}
 if(action==='finish-annotation'){state.annotation=false;board?.setEnabled(false);$('#entry-ink').classList.remove('drawing');$('#annotation-tools').innerHTML='';return;}
 if(action==='ink-undo')return board?.undo();if(action==='ink-redo')return board?.redo();
 if(action==='ink-clear')return confirmAction('筆跡を消しますか？','表示中の黒板の筆跡をすべて消します。消した直後は「元に戻す」で戻せます。',()=>board?.clear());
 if(action==='translate'){state.translationText=$('#translation-input').value.trim();if(!state.translationText)return toast('ことばや文章を入力してください');state.translation=analyzeText(state.translationText,state.direction,entries);save('translationText',state.translationText);renderTranslate();return;}
 if(action==='clear-translation'){state.translationText='';state.translation=null;save('translationText','');renderTranslate();return;}
 if(action==='translation-audio')return speak(speechText(state.translation?.output||'',entries)+(state.translation?.summary||''),'ことばの変換候補');
 if(action==='copy-translation')return copyText(state.translation?.output||'');
 if(action==='analyze-poem'){state.poemAnalysis=analyzePoem(state.poemText,state.poemType,state.poemReading,entries);savePoemDraft();renderPoetry();return;}
 if(action==='poem-audio')return speak((state.poemReading||speechText(state.poemText,entries)).replace(/\n/g,'。'),poemTypeName(state.poemType)+'の読み上げ');
 if(action==='save-poem'){if(!state.poemText.trim())return toast('作品を書いてください');const existing=state.poems.find(p=>p.text===state.poemText&&p.type===state.poemType);if(existing)existing.reading=state.poemReading;else state.poems.unshift({id:crypto.randomUUID(),type:state.poemType,text:state.poemText,reading:state.poemReading,created:new Date().toISOString()});save('poems',state.poems);renderPoetry();toast('作品帖に保存しました');return;}
 if(action==='poem-example'){const ex=Array.isArray(poemExamples)?poemExamples.find(e=>e.type===state.poemType):null;const fallback={haiku:['春の雨\n窓に小さな\n川をひく','はるのあめ\nまどにちいさな\nかわをひく'],senryu:['探し物\n探す眼鏡が\n頭上に','さがしもの\nさがすめがねが\nずじょうに'],tanka:['夕暮れの\n駅であなたを\n待つあいだ\n遠くの雲に\n色が生まれる','ゆうぐれの\nえきであなたを\nまつあいだ\nとおくのくもに\nいろがうまれる']}[state.poemType];state.poemText=ex?.text||fallback[0];state.poemReading=ex?.reading||fallback[1];state.poemAnalysis=null;savePoemDraft();renderPoetry();return;}
 if(action==='poem-to-classical'){state.translationText=state.poemText;state.direction='modern-classical';state.translation=analyzeText(state.translationText,state.direction,entries);navigate('translate');return;}
 if(action==='new-note'){const n={id:crypto.randomUUID(),title:'新しい黒板 '+(state.notes.length+1),strokes:[],text:'',grid:false};state.notes.push(n);state.noteId=n.id;save('notes',state.notes);save('noteId',state.noteId);renderNotebook();return;}
 if(action==='delete-note')return confirmAction('この黒板を削除しますか？','この黒板の筆跡と文字メモを削除します。必要なら画像やバックアップを先に保存してください。',()=>{state.notes=state.notes.filter(n=>n.id!==state.noteId);if(!state.notes.length)state.notes=[{id:crypto.randomUUID(),title:'新しい黒板',strokes:[],text:'',grid:false}];state.noteId=state.notes[0].id;save('notes',state.notes);save('noteId',state.noteId);renderNotebook();});
 if(action==='note-grid'){const n=currentNote();n.grid=!n.grid;save('notes',state.notes);$('#note-canvas-wrap').classList.toggle('grid',n.grid);return;}
 if(action==='note-download'){const data=board?.exportPNG?.('#17382f');if(data instanceof Blob)download(data,'kasai-blackboard.png');else if(typeof data==='string'){const a=document.createElement('a');a.href=data;a.download='kasai-blackboard.png';a.click();}else toast('画像を保存できませんでした');return;}
 if(action==='note-audio'){const note=currentNote();if(!note.text.trim())return toast('読み上げ用の文字メモを入力してください');return speak(note.text,note.title);}
});
function savePoemDraft(){save('poemType',state.poemType);save('poemText',state.poemText);save('poemReading',state.poemReading);}
$('#audio-play').onclick=playCurrent;$('#audio-stop').onclick=()=>reader.stop();$('#audio-next').onclick=()=>reader.next();$('#audio-prev').onclick=()=>reader.previous();$('#audio-loop').onclick=e=>{reader.loop=!reader.loop;e.currentTarget.setAttribute('aria-pressed',String(reader.loop));};$('#audio-continuous').onclick=e=>{reader.continuous=!reader.continuous;e.currentTarget.setAttribute('aria-pressed',String(reader.continuous));};$('#audio-speed').onchange=e=>{state.settings.rate=+e.target.value;reader.rate=state.settings.rate;save('settings',state.settings);};
$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#modal').addEventListener('close',()=>{if(modalBoard){modalBoard.destroy();modalBoard=null;}});window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==state.page)navigate(p);});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.page!=='dictionary'&&state.page!=='home')navigate('dictionary');$('#search-input')?.focus();}if(board&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();e.shiftKey?board.redo():board.undo();}});
icons();settingsApply();
async function boot(){try{const [data,source]=await Promise.all([fetch('./data/entries.json').then(r=>{if(!r.ok)throw Error('dictionary');return r.json();}),fetch('./data/sources.json').then(r=>r.ok?r.json():[]).catch(()=>[])]);entries=data;sources=Array.isArray(source)?source:source.sources||[];if(!entries.length)throw Error('empty');navigate(location.hash.slice(1)||'home');}catch{$('#main').innerHTML='<div class="empty-state"><h1 class="chalk">辞典を読み込めませんでした</h1><p>通信を確認して、もう一度開いてください。保存したメモは消えません。</p><button class="primary-button" id="retry-load">もう一度読み込む</button></div>';$('#retry-load').onclick=boot;}}
boot();
